WITH latest_tick AS MATERIALIZED (SELECT sampled_at FROM fleet_snapshots ORDER BY sampled_at DESC LIMIT 1), sampled_sessions AS MATERIALIZED (
 SELECT DISTINCT provider_id FROM fleet_snapshots WHERE sampled_at=(SELECT sampled_at FROM latest_tick) AND provider_id<>'coordinator' LIMIT 20
) SELECT json_build_object('kind','live_session_reputation_sample','sample_limit',20,'sample_selection','arbitrary_sessions_at_latest_snapshot_not_random','sampled_sessions',count(*),'reputation_rows',count(r.provider_id),'no_jobs',count(*) FILTER(WHERE r.total_jobs=0),'total_jobs',sum(r.total_jobs),'successful_jobs',sum(r.successful_jobs),'failed_jobs',sum(r.failed_jobs),'min_jobs',min(r.total_jobs),'max_jobs',max(r.total_jobs),'oldest_update',min(r.updated_at),'newest_update',max(r.updated_at),'snapshot_at',(SELECT sampled_at FROM latest_tick)) FROM sampled_sessions p LEFT JOIN provider_reputation r ON r.provider_id=p.provider_id;
